export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  // State observer & disturbance estimator variables
  let initialized = false;
  let px = 0, py = 0, pz = 0;
  let vx = 0, vy = 0, vz = 0;

  // Motor lag estimate and thrust scale K_T = sum_max_effective / mass
  // Nominal mass = 0.725, weakness = 0.125 -> K_T ~ 16 * (1 - 0.125/4) / 0.725 = 21.38
  let kT = 21.4;
  let motorTau = 0.04;
  let uThrustState = 0.45;
  let prevThrustCmd = 0.45;

  // Filtered velocity & model acceleration for vertical K_T estimation
  let vYf = 0, phiYf = 0;
  // Filtered velocity & model acceleration for horizontal wind disturbance
  let vXf = 0, aModXf = 0;
  let vZf = 0, aModZf = 0;

  // Estimated wind accelerations (c_d * wind)
  let baseWindAx = 0, baseWindAz = 0;
  let distAx = 0, distAz = 0;

  // Small position integral near targets
  let intX = 0, intY = 0, intZ = 0;
  let intYaw = 0;

  let lastGateIndex = 0;
  let committedCross = false;
  let touchdownLock = false;

  return {
    step(obs) {
      const dt = 0.01;
      const g = 9.81;
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      if (!initialized) {
        initialized = true;
        px = p.x; py = p.y; pz = p.z;
        vx = v.x; vy = v.y; vz = v.z;
        vYf = v.y; phiYf = 0.45;
        vXf = v.x; vZf = v.z;
      } else {
        // Kinematic Kalman-like fusion of pos and vel
        px = 0.35 * (px + vx * dt) + 0.65 * p.x;
        py = 0.35 * (py + vy * dt) + 0.65 * p.y;
        pz = 0.35 * (pz + vz * dt) + 0.65 * p.z;
        vx = 0.30 * vx + 0.70 * v.x;
        vy = 0.30 * vy + 0.70 * v.y;
        vz = 0.30 * vz + 0.70 * v.z;
      }

      // Update motor thrust lag state
      const alphaMotor = 1 - Math.exp(-dt / motorTau);
      uThrustState += (prevThrustCmd - uThrustState) * alphaMotor;

      // Actual thrust direction from measured attitude
      const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
      const bodyZ = -Math.sin(att.roll);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = Math.cos(att.pitch) * Math.cos(att.roll);
      const dirZ = -sy * bodyX + cy * bodyZ;

      const estMass = clamp(15.2 / kT, 0.60, 0.85);
      const cd = 0.42 / estMass;

      // 1. Online K_T estimation when airborne (no vertical wind exists!)
      if (py > 0.11 && obs.t > 0.08 && !touchdownLock) {
        const tauY = 0.06;
        const aY = Math.exp(-dt / tauY);
        const phiY = uThrustState * dirY;
        vYf = aY * vYf + (1 - aY) * vy;
        phiYf = aY * phiYf + (1 - aY) * phiY;
        const lhsY = (vy - vYf) / tauY + g + cd * vYf;
        if (phiYf > 0.25 && obs.t > 0.15) {
          const errKT = lhsY - kT * phiYf;
          const gain = obs.t < 1.8 ? 1.8 : 0.4;
          kT = clamp(kT + gain * errKT * phiYf * dt * 10, 17.2, 27.0);
        }
      } else {
        vYf = vy;
        phiYf = uThrustState * dirY;
      }

      // 2. Horizontal disturbance observer (wind + gusts)
      // Also use vertical acceleration to infer instantaneous total thrust sum/m!
      const tauW = 0.035;
      const aW = Math.exp(-dt / tauW);
      const aThrustMag = kT * uThrustState;
      const aModX = aThrustMag * dirX - cd * vx;
      const aModZ = aThrustMag * dirZ - cd * vz;

      if (py > 0.10 && obs.t > 0.06 && !touchdownLock) {
        vXf = aW * vXf + (1 - aW) * vx;
        vZf = aW * vZf + (1 - aW) * vz;
        aModXf = aW * aModXf + (1 - aW) * aModX;
        aModZf = aW * aModZf + (1 - aW) * aModZ;

        const rawDistX = (vx - vXf) / tauW - aModXf;
        const rawDistZ = (vz - vZf) / tauW - aModZf;

        distAx = clamp(0.25 * distAx + 0.75 * rawDistX, -4.5, 4.5);
        distAz = clamp(0.25 * distAz + 0.75 * rawDistZ, -4.5, 4.5);

        // Before t = 1.95s, there are NO gusts (gustStartMin = 2.0s), only baseWind!
        if (obs.t > 0.20 && obs.t < 1.95) {
          baseWindAx = 0.92 * baseWindAx + 0.08 * distAx;
          baseWindAz = 0.92 * baseWindAz + 0.08 * distAz;
        }
      } else {
        vXf = vx; vZf = vz;
        aModXf = aModX; aModZf = aModZ;
        distAx = baseWindAx; distAz = baseWindAz;
      }

      // Reset gate commitment when gateIndex advances
      if (obs.gateIndex !== lastGateIndex) {
        lastGateIndex = obs.gateIndex;
        committedCross = false;
        intX *= 0.3; intY *= 0.3; intZ *= 0.3;
      }

      // 3. Trajectory & Waypoint Generation
      let tx, ty, tz;
      let desVx = 0, desVy = 0, desVz = 0;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        // Lookahead prediction of y and z in 0.12s
        const predY = py + vy * 0.12;
        const predZ = pz + vz * 0.12;
        const errY = Math.abs(py - gate.y);
        const errZ = Math.abs(pz - gate.z);
        const predErrY = Math.abs(predY - gate.y);
        const predErrZ = Math.abs(predZ - gate.z);

        // Always target gate.y and gate.z directly
        ty = gate.y;
        tz = gate.z;

        // Check if aligned well enough to pass through gate plane
        const aligned = (errZ < 0.085 && predErrZ < 0.085 && errY < 0.16 && predErrY < 0.16);
        if (px > gate.x - 0.14 && aligned && vx > 0.15) {
          committedCross = true;
        }

        const distToGateX = gate.x - px;
        if (committedCross || aligned) {
          // Fly smoothly through the gate!
          tx = gate.x + 0.35;
          // Feedforward cruise speed in x when well aligned
          if (distToGateX > 0.25) {
            desVx = clamp(1.1 * distToGateX, 0.35, 0.95);
          } else {
            desVx = 0.70;
          }
        } else {
          // Hold safely in front of gate plane while y/z align
          const holdX = gate.x - 0.26;
          tx = Math.min(px + 0.35, holdX);
          desVx = clamp(1.2 * (holdX - px), -0.4, 0.65);
        }

        // Smooth feedforward velocity in z and y when far in x from gate
        if (distToGateX > 0.35) {
          const tEst = clamp(distToGateX / 0.85, 0.35, 1.5);
          desVz = clamp((gate.z - pz) / tEst, -0.75, 0.75) * 0.5;
          desVy = clamp((gate.y - py) / tEst, -0.75, 0.75) * 0.5;
        }
      } else {
        // Gate 3 passed -> fly to landing pad (2.05, 0, 1.65)
        const pad = obs.pad.centre;
        const distXZ = Math.hypot(pad.x - px, pad.z - pz);
        const speedXZ = Math.hypot(vx, vz);
        const speed3D = Math.hypot(vx, vy, vz);

        tx = pad.x;
        tz = pad.z;

        // Check touchdown lock
        if ((py <= 0.082 && distXZ <= 0.115 && speed3D < 0.42) ||
            (touchdownLock && distXZ <= 0.138 && py <= 0.092)) {
          touchdownLock = true;
          prevThrustCmd = 0;
          return { thrust: 0, roll: 0, pitch: 0, yawRate: 0 };
        }
        touchdownLock = false;

        if (distXZ > 0.25) {
          // Glide slope descent while approaching pad horizontally
          ty = clamp(0.18 + 0.65 * distXZ, 0.18, 1.05);
          desVy = clamp(-0.45 * (py - ty), -0.55, 0.2);
        } else if (distXZ > 0.10 || speedXZ > 0.25) {
          // Fine alignment right above pad
          ty = 0.12;
          desVy = -0.15;
        } else {
          // Directly over pad -> soft vertical descent into touchdown
          ty = 0.03;
          desVy = py > 0.14 ? -0.28 : -0.18;
        }
      }

      // 4. Position & Velocity Feedback + Disturbance Rejection
      const ex = tx - px, ey = ty - py, ez = tz - pz;
      const evx = desVx - vx, evy = desVy - vy, evz = desVz - vz;

      if (Math.abs(ex) < 0.35 && py > 0.10) intX = clamp(intX + ex * dt, -0.35, 0.35);
      if (Math.abs(ez) < 0.35 && py > 0.10) intZ = clamp(intZ + ez * dt, -0.35, 0.35);
      if (Math.abs(ey) < 0.40 && py > 0.10) intY = clamp(intY + ey * dt, -0.45, 0.45);

      const kpXZ = obs.gateIndex < 3 ? 5.8 : 5.2;
      const kdXZ = obs.gateIndex < 3 ? 4.4 : 4.2;
      const kiXZ = 1.2;

      // Desired world accelerations
      const axDes = kpXZ * ex + kdXZ * evx + kiXZ * intX + cd * vx - distAx;
      const azDes = kpXZ * ez + kdXZ * evz + kiXZ * intZ + cd * vz - distAz;
      const ayDes = clamp(6.5 * ey + 4.2 * evy + 1.8 * intY + cd * vy, -4.5, 5.5);

      const axClamped = clamp(axDes, -5.0, 5.0);
      const azClamped = clamp(azDes, -5.0, 5.0);
      const ayTotal = Math.max(2.0, g + ayDes);

      // Exact nonlinear conversion from desired world thrust acceleration (ax, ayTotal, az) to (roll, pitch, thrust)
      const aMag = Math.hypot(axClamped, ayTotal, azClamped);
      const dxDes = axClamped / aMag;
      const dyDes = ayTotal / aMag;
      const dzDes = azClamped / aMag;

      const bodyXDes = cy * dxDes - sy * dzDes;
      const bodyZDes = sy * dxDes + cy * dzDes;

      const rollDes = clamp(-Math.asin(clamp(bodyZDes, -0.95, 0.95)), -0.52, 0.52);
      const pitchDes = clamp(Math.atan2(bodyXDes, dyDes), -0.52, 0.52);

      // Attitude lead compensation to speed up inner attitude loop response against gusts
      const kLead = 0.85, kRate = 0.05;
      const rollCmd = clamp(rollDes + kLead * (rollDes - att.roll) - kRate * rates.roll, -0.6, 0.6);
      const pitchCmd = clamp(pitchDes + kLead * (pitchDes - att.pitch) - kRate * rates.pitch, -0.6, 0.6);

      // Thrust command: project required vertical acceleration onto current thrust direction
      const thrust = clamp((ayTotal / Math.max(0.65, dirY)) / kT, 0.05, 1.0);
      prevThrustCmd = thrust;

      // Yaw control with integral to cancel weak-motor yaw torque
      if (py > 0.10) intYaw = clamp(intYaw + att.yaw * dt, -0.4, 0.4);
      const yawRate = clamp(-3.2 * att.yaw - 1.8 * intYaw - 0.25 * rates.yaw, -2, 2);

      return { thrust, roll: rollCmd, pitch: pitchCmd, yawRate };
    },
  };
}

