        }
        touchdownLock = false;

        desVx = profileVel(tx - px, 2.5, 1.6, 0.90);
        desVz = profileVel(tz - pz, 2.5, 1.6, 0.90);

        if (distXZ > 0.22) {
          ty = clamp(0.16 + 0.65 * distXZ, 0.16, 1.05);
          desVy = profileVel(ty - py, 2.4, 1.8, 0.85);
        } else if (distXZ > 0.095 || speedXZ > 0.22) {
          ty = 0.11;
          desVy = profileVel(ty - py, 2.4, 1.5, 0.45);
        } else {
          ty = 0.03;
          desVy = py > 0.14 ? -0.28 : -0.18;
        }
      }

      // 4. Cascade Velocity Tracking + Small Position Integral + Disturbance Rejection
      const ex = tx - px, ey = ty - py, ez = tz - pz;
      const evx = desVx - vx, evy = desVy - vy, evz = desVz - vz;

      if (Math.abs(ex) < 0.25 && py > 0.14) intX = clamp(intX + ex * dt, -0.30, 0.30);
      else intX *= 0.98;
      if (Math.abs(ez) < 0.25 && py > 0.14) intZ = clamp(intZ + ez * dt, -0.30, 0.30);
