        vZf = aW * vZf + (1 - aW) * vz;
        vYw = aW * vYw + (1 - aW) * vy;
        aModXf = aW * aModXf + (1 - aW) * aModX;
        aModZf = aW * aModZf + (1 - aW) * aModZ;

        const ayMeas = (vy - vYw) / tauW + g + cd * vYw;
        const aThrustFromY = clamp(ayMeas / Math.max(0.7, dirY), 0, 28);
        const aModXFromY = aThrustFromY * dirX - cd * vXf;
        const aModZFromY = aThrustFromY * dirZ - cd * vZf;

        const blendModX = 0.35 * aModXf + 0.65 * aModXFromY;
        const blendModZ = 0.35 * aModZf + 0.65 * aModZFromY;

